import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { QrReader } from 'react-qr-reader';
import './Login.css';
import { loginUser } from '../utils/authService';

const Login = ({ setUser }) => {
  const [employeeId, setEmployeeId] = useState('');
  const [password, setPassword] = useState('');
  const [errorMessage, setErrorMessage] = useState('');
  const [showForgotPassword, setShowForgotPassword] = useState(false);
  const [forgotEmail, setForgotEmail] = useState('');
  const [resetMessage, setResetMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showQRScan, setShowQRScan] = useState(false);
  const [qrReaderKey, setQrReaderKey] = useState(0);
  const [pendingUser, setPendingUser] = useState(null);
  const [cameraReady, setCameraReady] = useState(false);
  const [cameraError, setCameraError] = useState('');
  const isMountedRef = useRef(true);
  const navigate = useNavigate();

  useEffect(() => {
    isMountedRef.current = true;
    
    // Suppress console warnings
    const originalWarn = console.warn;
    const originalError = console.error;
    
    console.warn = function(...args) {
      const message = String(args[0]);
      if (message.includes('Canvas2D') || 
          message.includes('willReadFrequently') ||
          message.includes('HTMLCanvasElementLuminanceSource') ||
          message.includes('getImageData') ||
          message.includes('Multiple readback operations')) {
        return;
      }
      originalWarn(...args);
    };

    console.error = function(...args) {
      const message = String(args[0]);
      if (message.includes('Canvas2D') || 
          message.includes('willReadFrequently') ||
          message.includes('HTMLCanvasElementLuminanceSource') ||
          message.includes('getImageData')) {
        return;
      }
      originalError(...args);
    };

    if (showQRScan) {
      requestCameraPermission();
    }

    const requestCameraPermission = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: false 
        });
        stream.getTracks().forEach(track => track.stop());
        if (isMountedRef.current) {
          setCameraReady(true);
          setCameraError('');
        }
      } catch (error) {
        if (isMountedRef.current) {
          setCameraReady(false);
          setCameraError('Camera access denied. Please grant camera permissions.');
        }
      }
    };

    return () => {
      isMountedRef.current = false;
      console.warn = originalWarn;
      console.error = originalError;
    };
  }, [showQRScan]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setErrorMessage('');
    setIsLoading(true);

    if (!employeeId || !password) {
      setErrorMessage('Please enter both Employee ID and Password');
      setIsLoading(false);
      return;
    }

    const result = loginUser(employeeId, password);

    if (result.success) {
      setUser(result.user);
      
      // Redirect based on role
      setTimeout(() => {
        if (result.user.userRole === 'admin') {
          navigate('/attendance-scanner');
        } else if (result.user.userRole === 'manager') {
          navigate('/attendance-scanner');
        } else {
          navigate('/attendance-scanner');
        }
      }, 500);
    } else {
      setErrorMessage(result.error || 'Login failed. Please try again.');
    }
    
    setIsLoading(false);
  };

  const handleForgotPassword = (e) => {
    e.preventDefault();
    setResetMessage('');

    if (!forgotEmail) {
      setResetMessage('Please enter your email address');
      return;
    }

    // Simulate email sending
    setResetMessage('✅ Password reset link has been sent to your email. Please check your inbox.');
    setTimeout(() => {
      setShowForgotPassword(false);
      setForgotEmail('');
      setResetMessage('');
    }, 3000);
  };

  return (
    <div className="login-container">
      <div className="login-box">
        <div className="login-logo">🔐</div>
        <h2>Login</h2>
        <p>Please Enter your ID and Password</p>
        
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <input
              type="text"
              placeholder="Enter Employee ID"
              value={employeeId}
              onChange={(e) => setEmployeeId(e.target.value)}
              disabled={isLoading}
              className="login-input"
            />
          </div>

          <div className="form-group">
            <input
              type="password"
              placeholder="Enter Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              disabled={isLoading}
              className="login-input"
            />
          </div>

          <button 
            type="submit" 
            disabled={isLoading}
            className="login-btn"
          >
            {isLoading ? 'Signing In...' : 'Sign In'}
          </button>
          
          {errorMessage && (
            <div className="error-message">
              ❌ {errorMessage}
            </div>
          )}
        </form>

        <div className="login-footer">
          <button 
            className="forgot-password-btn"
            onClick={() => setShowForgotPassword(true)}
          >
            Forgot Password?
          </button>
        </div>

        <div className="demo-info">
          <strong>🧪 Test Credentials:</strong>
          <p><strong>Admin:</strong> admin (any password)</p>
          <p><strong>Manager:</strong> manager (any password)</p>
          <p><strong>Employee:</strong> employee (any password)</p>
          <p style={{ marginTop: '8px', fontSize: '11px', color: '#888' }}>
            💡 Tip: Try different roles to see role-based dashboards
          </p>
        </div>
      </div>

      {/* Forgot Password Modal */}
      {showForgotPassword && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h3>Reset Password</h3>
              <button 
                className="modal-close"
                onClick={() => {
                  setShowForgotPassword(false);
                  setForgotEmail('');
                  setResetMessage('');
                }}
              >
                ✕
              </button>
            </div>

            <form onSubmit={handleForgotPassword} className="reset-form">
              <p className="reset-description">
                Enter your email address and we'll send you a link to reset your password.
              </p>

              <div className="form-group">
                <label>Email Address</label>
                <input
                  type="email"
                  placeholder="Enter your email"
                  value={forgotEmail}
                  onChange={(e) => setForgotEmail(e.target.value)}
                  className="login-input"
                />
              </div>

              {resetMessage && (
                <div className={`reset-message ${resetMessage.includes('✅') ? 'success' : 'error'}`}>
                  {resetMessage}
                </div>
              )}

              <div className="modal-buttons">
                <button
                  type="button"
                  className="btn-cancel"
                  onClick={() => {
                    setShowForgotPassword(false);
                    setForgotEmail('');
                    setResetMessage('');
                  }}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="btn-submit"
                >
                  Send Reset Link
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Login;
